const SECRET_HEADER = 'x-n8n-webhook-secret'
const FACT_KEYS = [
  'discrepancyId',
  'auditId',
  'statementId',
  'platform',
  'statementPeriod',
  'trackName',
  'plays',
  'territory',
  'actualPayout',
  'expectedPayout',
  'difference',
  'threshold',
  'discrepancyStatus',
  'artistName',
]

function readHeader(headers, name) {
  if (!headers || typeof headers !== 'object') return undefined
  const target = name.toLowerCase()
  for (const key of Object.keys(headers)) {
    if (key.toLowerCase() === target) {
      const value = headers[key]
      return Array.isArray(value) ? value[0] : value
    }
  }
  return undefined
}

const configuredSecret = $env.N8N_WEBHOOK_SECRET
const item = $input.first().json
const suppliedSecret = readHeader(item.headers || {}, SECRET_HEADER)

if (!configuredSecret) throw new Error('N8N_WEBHOOK_SECRET is not configured')
if (!suppliedSecret || suppliedSecret !== configuredSecret) {
  throw new Error('Invalid or missing webhook secret')
}

const body = item.body && typeof item.body === 'object' ? item.body : item
const facts = body.discrepancy

if (!facts || typeof facts !== 'object' || Array.isArray(facts)) {
  throw new Error('discrepancy facts are required')
}

const missing = FACT_KEYS.filter(function (key) {
  const value = facts[key]
  return value === undefined || value === null || String(value).trim() === ''
})

if (missing.length > 0) {
  throw new Error('discrepancy facts are missing: ' + missing.join(', '))
}

return [{ json: { facts: facts } }]

