const FACTS = $('Validate Draft Request').first().json.facts
const output = $input.first().json.output

if (!output || typeof output !== 'object' || Array.isArray(output)) {
  throw new Error('AI dispute draft must be an object')
}

const allowedKeys = ['subject', 'body', 'facts_used', 'missing_information']
for (const key of Object.keys(output)) {
  if (allowedKeys.indexOf(key) === -1) throw new Error('unsupported field ' + key)
}

const subject = typeof output.subject === 'string' ? output.subject.trim() : ''
const body = typeof output.body === 'string' ? output.body.trim() : ''
if (!subject || subject.length > 255) throw new Error('subject is required and must be 255 characters or fewer')
if (!body || body.length > 20000) throw new Error('body is required and must be 20,000 characters or fewer')

if (!Array.isArray(output.facts_used)) throw new Error('facts_used must be an array')
if (!Array.isArray(output.missing_information)) throw new Error('missing_information must be an array')

const allowedFactKeys = Object.keys(FACTS)
const factsUsed = output.facts_used.map(function (value) {
  const path = String(value).trim()
  if (allowedFactKeys.indexOf(path) === -1) throw new Error('facts_used contains unsupported fact path ' + path)
  return path
})

const missingInformation = output.missing_information.map(function (value) {
  return String(value).trim()
})

return [{
  json: {
    subject: subject,
    body: body,
    facts_used: factsUsed,
    missing_information: missingInformation,
  },
}]
